function change_page_size(){let e=document.getElementById("select_page_size").value;document.getElementById("id_page_size").value=e,document.getElementById("act").value="",$("#searchForm").submit()}function delete_evidence_list(){document.getElementById("act").value="del",$("#searchForm").submit()}const $modal=document.getElementById("del-record"),$openButton=document.querySelectorAll("#open"),$closeButton=document.querySelectorAll("#close"),$deleteButton=document.querySelectorAll("#delete");let $deleteFlg=!1;for(let e=0;e<$openButton.length;e++)$openButton[e].addEventListener("click",e=>{$deleteFlg=!0});for(let e=0;e<$closeButton.length;e++)$closeButton[e].addEventListener("click",()=>{$modal.close()});for(let e=0;e<$deleteButton.length;e++)$deleteButton[e].addEventListener("click",()=>{$modal.close(),delete_evidence_list()});$(function(){$("tr[data-href]").on("click",function(e){if($deleteFlg){$deleteFlg=!1;let e=$(this).data("href"),t=e.indexOf("edit_report"),l=e.substring(t+12,t+26);document.getElementById("report_id").value=l,$modal.showModal()}else 0==$(e.target).closest(".prosessing").length?location.href=$(this).data("href"):show_message("処理中です。")}),$("#ev_table").tablesorter({headers:{1:{sorter:!1},2:{sorter:!1},3:{sorter:!1},4:{sorter:!1},5:{sorter:!1}}})}),$("#id_report_month").change(function(){let e=document.getElementById("select_page_size").value;document.getElementById("id_page_size").value=e,document.getElementById("act").value="";$(this).val();document.SearchForm.submit()});